  if (select module_id from public.assessments where id = v_aid) is distinct from '38b2ee69-f7d3-5de2-8208-b1fa31501558'::uuid then
    raise exception 'Тест a2-m03 прив’язаний не до модуля A2.3 — звірте базу';
  end if;
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
