    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.', estimated_minutes = 6 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('17cb9440-bd2c-5f4c-9c96-6a5b4d35e208', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Мої діти не знають, що таке відеокасета.", "Актрисою? Та ти й сьогодні справжня актриса!", "Шкода кінотеатру. Мабуть, там було гарно."]'::jsonb, 0, null, '{}'::text[], 'Moja djeca ne znaju što je videokazeta.', null, null, 'Прозвучало: «Moja djeca ne znaju što je videokazeta.» — «Мої діти не знають, що таке відеокасета.».', (select id from public.lessons where id = 'b22c7dff-1657-5dad-94a6-5d059e346da8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('05509964-673e-599f-9bf3-3aec16a7064b', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["А я на контрольній мала шпаргалку в пеналі!", "Тоді добре бережи його, це сімейний скарб.", "Дуже пустотливим. Постійно лазив по деревах."]'::jsonb, 0, null, '{}'::text[], 'Ja sam na kontrolnom imala šalabahter u pernici!', null, null, 'Прозвучало: «Ja sam na kontrolnom imala šalabahter u pernici!» — «А я на контрольній мала шпаргалку в пеналі!».', (select id from public.lessons where id = '92226a59-39e3-5dba-b0df-1e91b3dd2210'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6469e12b-20ea-5dfe-a8c7-ce6741b4392f', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'Хто допоміг їй знайти квартиру?', 'Preseljenje koje je sve promijenilo', '["Колега з роботи", "Сусідка Марія", "Агенція"]'::jsonb, 1, null, '{}'::text[], null, 'Prije tri godine spakirala sam jedan kofer i napustila rodno mjesto. Bilo je teško ostaviti iza sebe kuću, prijatelje i posao. Prvi mjeseci u Hrvatskoj bili su puni neizvjesnosti. Nisam znala jezik i često sam se osjećala izgubljeno. Ponekad mi je bilo teško zbog samoće. Ali susjedi su mi bili velika podrška: susjeda Marija pomogla mi je naći stan, a njezin muž mi je pokazao grad. Polako sam se priviknula na novi život. Kad sam našla posao, osjetila sam veliko olakšanje. Danas mislim da je preseljenje bilo prekretnica u mom životu. Ponosna sam na sebe i na svoju hrabrost.', 'Три роки тому я спакувала одну валізу й покинула рідне місто. Було важко залишити позаду дім, друзів і роботу. Перші місяці в Хорватії були сповнені невизначеності. Я не знала мови й часто почувалася розгубленою. Іноді мені було важко через самотність. Але сусіди дуже мене підтримали: сусідка Марія допомогла мені знайти квартиру, а її чоловік показав мені місто. Поступово я звикла до нового життя. Коли я знайшла роботу, то відчула велике полегшення. Сьогодні я думаю, що переїзд став поворотним моментом у моєму житті. Я пишаюся собою і своєю сміливістю.', 'Текст «Переїзд, що змінив усе». Правильна відповідь: «Сусідка Марія».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('e0250571-e4c5-5e02-8868-3d426947b05b', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Darja, sjećaš li se svoje prve učiteljice?', '["Mi bismo htjeli neko mirno mjesto, bez velike gužve.", "Sjećam se, bila je stroga, ali pravedna.", "Volio bi igrati vaterpolo, ali članarina je skupa."]'::jsonb, 1, null, '{}'::text[], 'Darja, sjećaš li se svoje prve učiteljice?', null, null, 'Діалог «Пам’ятаєш?»: «Darja, sjećaš li se svoje prve učiteljice?» (Дар’є, ти пам’ятаєш свою першу вчительку?) — «Sjećam se, bila je stroga, ali pravedna.» (Пам’ятаю, вона була сувора, але справедлива.).', (select id from public.lessons where id = '92226a59-39e3-5dba-b0df-1e91b3dd2210'), 'PUBLISHED', 'claude_assessment_v5'),
  ('f9a3c477-5dc4-5ef7-8130-1e4d8f85ec32', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Imate li djece?', '["Medicinska sestra je regulirana profesija, pa treba stručno priznavanje.", "Imamo dvoje. Filip se rodio godinu dana kasnije.", "Postoji. Traži se i poznavanje hrvatskog na razini B2."]'::jsonb, 1, null, '{}'::text[], 'Imate li djece?', null, null, 'Діалог «Дати мого життя»: «Imate li djece?» (У вас є діти?) — «Imamo dvoje. Filip se rodio godinu dana kasnije.» (Маємо двох. Філіп народився через рік.).', (select id from public.lessons where id = 'c8c098bc-973f-5a79-b42a-5ec5c7152d09'), 'PUBLISHED', 'claude_assessment_v5'),
  ('34b14d15-4a78-516c-9fb7-046470b3a26d', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Jeste li dobili kaznu?', '["Jesmo. Jako smo se posramili, nikad to neću zaboraviti.", "U Supetru. Vozači moraju sići do auta prije pristajanja.", "Zahtjev nije odbijen, ali nedostaje dodatak diplomi."]'::jsonb, 0, null, '{}'::text[], 'Jeste li dobili kaznu?', null, null, 'Діалог «Прогул»: «Jeste li dobili kaznu?» (Вас покарали?) — «Jesmo. Jako smo se posramili, nikad to neću zaboraviti.» (Так. Нам було дуже соромно, я ніколи цього не забуду.).', (select id from public.lessons where id = '92226a59-39e3-5dba-b0df-1e91b3dd2210'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d1cfbb69-816c-5828-924c-e6f9e25e06fc', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Žive li obje u Zagrebu?', '["На річницю шлюбу батьків, щороку в червні.", "Обидві. А батьки обоє в Осієку.", "Нас троє дітей. Я найстарший, а сестри — близнючки."]'::jsonb, 1, null, '{}'::text[], null, 'Daša: Marko, koliko vas je u obitelji?
Marko: Nas je troje djece. Ja sam najstariji, a sestre su blizanke.
Daša: Žive li obje u Zagrebu?
Marko: Obje. A roditelji su oboje u Osijeku.
Daša: Kad se nađete svi zajedno?
Marko: Za obljetnicu braka roditelja, svake godine u lipnju.', 'Daša: Марку, скільки вас у родині?
Marko: Нас троє дітей. Я найстарший, а сестри — близнючки.
Daša: Обидві живуть у Загребі?
Marko: Обидві. А батьки обоє в Осієку.
Daša: Коли ви збираєтеся всі разом?
Marko: На річницю шлюбу батьків, щороку в червні.', 'Діалог «Велика родина»: «Žive li obje u Zagrebu?» — «Obje. A roditelji su oboje u Osijeku.», тобто «Обидві. А батьки обоє в Осієку.».', (select id from public.lessons where id = 'c8c098bc-973f-5a79-b42a-5ec5c7152d09'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d88fece8-5e2b-5765-9251-1cf28a84996b', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kino su srušili?', '["Це був новий початок.", "Так, десять років тому. Місто дуже змінилося.", "У центрі нашого міста. Тоді тут був кінотеатр, а тепер торговий центр."]'::jsonb, 1, null, '{}'::text[], null, 'Darja: Vidi ovu crno-bijelu fotografiju. To je moja baka prije pedeset godina.
Daša: Kako je lijepa! A gdje je ovo?
Darja: U centru našeg grada. Tada je tu bilo kino, a sad je trgovački centar.
Daša: Kino su srušili?
Darja: Jesu, prije deset godina. Grad se jako promijenio.
Daša: Šteta za kino. Sigurno je bilo lijepo.', 'Darja: Подивись на цю чорно-білу фотографію. Це моя бабуся п’ятдесят років тому.
Daša: Яка гарна! А де це?
Darja: У центрі нашого міста. Тоді тут був кінотеатр, а тепер торговий центр.
Daša: Кінотеатр знесли?
Darja: Так, десять років тому. Місто дуже змінилося.
Daša: Шкода кінотеатру. Мабуть, там було гарно.', 'Діалог «Старі фото»: «Kino su srušili?» — «Jesu, prije deset godina. Grad se jako promijenio.», тобто «Так, десять років тому. Місто дуже змінилося.».', (select id from public.lessons where id = 'b22c7dff-1657-5dad-94a6-5d059e346da8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('4f0dfbe7-5923-5c88-a482-e140875921db', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я сумую за мамою». Що ви скажете?', null, '["Moram ti ispričati što se dogodilo.", "Nedostaje mi mama.", "Nekoć je ovdje bila tvornica."]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Я сумую за мамою.» — «Nedostaje mi mama.».', (select id from public.lessons where id = '3dfc3a66-be3b-5760-8273-f00b5cb03871'), 'PUBLISHED', 'claude_assessment_v5'),
  ('7108b58a-f1a9-58e3-83d2-a8eb099874f6', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «тоді»', null, '[]'::jsonb, null, 'tada', '{}'::text[], null, null, null, '«тоді» — tada.', (select id from public.lessons where id = 'b22c7dff-1657-5dad-94a6-5d059e346da8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('937569fe-7575-502a-8d8a-a6f1a2b47ba2', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Ми обоє народилися в Києві.»', null, '["smo", "rođeni", "Kijevu.", "Oboje", "u"]'::jsonb, null, 'Oboje smo rođeni u Kijevu.', array['U Kijevu smo oboje rođeni.']::text[], null, null, null, '«Ми обоє народилися в Києві.» — «Oboje smo rođeni u Kijevu.».', (select id from public.lessons where id = 'c8c098bc-973f-5a79-b42a-5ec5c7152d09'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6e6fa333-75e5-591b-ad98-f85c306f2219', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Ким ти мріяв бути?»', null, '[]'::jsonb, null, 'Što si maštao biti?', '{}'::text[], null, null, null, '«Ким ти мріяв бути?» — «Što si maštao biti?».', (select id from public.lessons where id = '65e0eec5-f830-5509-a807-db00ace41075'), 'PUBLISHED', 'claude_assessment_v5');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, 'PUBLISHED', 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірки рівня A2 наново за схемою 2026-11-07 після плану «Дублі й сенс уроків» (PR 3–4) — завдання й хибні варіанти лише з уроків і текстів, які є в курсі зараз (задача власника 2026-11-19). Потрібна перевірка носієм.');
end $$;

-- Перевірка модуля A2.4 · 14 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a2-m04' and cefr = 'A2';
  if v_aid is null then raise exception 'Немає тесту a2-m04 — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = '1c4e590a-0264-505e-b08e-9ebefa9acaaa') then return; end if;  -- уже оновлено
  if (select module_id from public.assessments where id = v_aid) is distinct from '8fad33b4-f461-5119-b5e5-f94b700e283c'::uuid then
    raise exception 'Тест a2-m04 прив’язаний не до модуля A2.4 — звірте базу';
  end if;
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Після модуля: 14 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~7 хв.', estimated_minutes = 7 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('1c4e590a-0264-505e-b08e-9ebefa9acaaa', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["І велосипеди в спільному приміщенні серед дитячих візків.", "Згоден. Трохи поваги до інших — і всі житимемо спокійно.", "До шістдесяти днів. Адміністративний збір сплачують перед поданням."]'::jsonb, 1, null, '{}'::text[], 'Slažem se. Malo obzira i svi ćemo živjeti mirno.', null, null, 'Прозвучало: «Slažem se. Malo obzira i svi ćemo živjeti mirno.» — «Згоден. Трохи поваги до інших — і всі житимемо спокійно.».', (select id from public.lessons where id = '5252662a-abfc-517a-9bde-8683121a53c5'), 'PUBLISHED', 'claude_assessment_v5'),
  ('bc4fdcbb-b5d7-5e52-9426-99ff453d6bc4', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Хтось постійно паркується перед під’їздом.", "Як на мене, життя в селі краще для дітей.", "У вас є страховка квартири? Нам знадобиться відшкодування збитків."]'::jsonb, 2, null, '{}'::text[], 'Imate li osiguranje stana? Trebat će nam nadoknada štete.', null, null, 'Прозвучало: «Imate li osiguranje stana? Trebat će nam nadoknada štete.» — «У вас є страховка квартири? Нам знадобиться відшкодування збитків.».', (select id from public.lessons where id = '5252662a-abfc-517a-9bde-8683121a53c5'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6bb3dd1b-649c-5235-bb4d-21e558849c4f', v_aid, 3, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Бухгалтери затребувані. Ви можете отримати ваучер на навчання.", "Передай бабусі вітання від мене. Тримайся!", "Тут багато хто святкує. Твоє привітання мене дуже потішило."]'::jsonb, 2, null, '{}'::text[], 'Ovdje mnogi slave. Tvoja čestitka me jako obradovala.', null, null, 'Прозвучало: «Ovdje mnogi slave. Tvoja čestitka me jako obradovala.» — «Тут багато хто святкує. Твоє привітання мене дуже потішило.».', (select id from public.lessons where id = '75a84442-280d-56be-b746-81ca57caa0b5'), 'PUBLISHED', 'claude_assessment_v5'),
  ('604c1352-ec41-524d-8666-8047f729d34c', v_aid, 4, 'A2', 'reading', 'understand', 'multiple_choice', 'Що нового в роботі Олени?', 'Pismo prijateljici u Ukrajini', '["Вона працює в готелі", "Вона не працює", "Вона працює в дитсадку"]'::jsonb, 2, null, '{}'::text[], null, 'Draga Ira,
dugo ti se nisam javila, oprosti! Ovdje je sve dobro. Djeca su se navikla na školu i već imaju prijatelje. Sofija je u razredu najbolja iz matematike, a Danilo igra nogomet. Ja sam promijenila posao: sada radim u vrtiću kao pomoćnica odgojiteljice. Posao mi se jako sviđa, iako je plaća mala. Hrvatski mi ide sve bolje, ali još uvijek griješim. Puno mislim na tebe i na naš grad. Kad ćeš doći u posjet? Imamo mali stan, ali za tebe ćemo naći mjesto.
Grlim te,
Olena', 'Люба Іро!
Я давно тобі не писала, вибач! Тут усе добре. Діти звикли до школи й уже мають друзів. Софія найкраща в класі з математики, а Данило грає у футбол. Я змінила роботу: тепер працюю в дитячому садку помічницею вихователя. Робота мені дуже подобається, хоча зарплата маленька. Хорватська дається мені дедалі краще, але я досі помиляюся. Я багато думаю про тебе і про наше місто. Коли ти приїдеш у гості? У нас маленька квартира, але для тебе ми знайдемо місце.
Обіймаю тебе,
Олена', 'Текст «Лист подрузі в Україну». Правильна відповідь: «Вона працює в дитсадку».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('622af242-a7dd-55d5-a05b-f3bd9ef2b047', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Je li duhovit?', '["Sjećam se, bila je stroga, ali pravedna.", "Pišu, učiteljica im provjeri zadaću. Ručak je u školskoj kuhinji.", "Jest, kad ga bolje upoznaš. Lako se slaže s ljudima."]'::jsonb, 2, null, '{}'::text[], 'Je li duhovit?', null, null, 'Діалог «Новий колега»: «Je li duhovit?» (Він дотепний?) — «Jest, kad ga bolje upoznaš. Lako se slaže s ljudima.» (Так, коли краще його пізнаєш. Він легко ладнає з людьми.).', (select id from public.lessons where id = '7b43692b-44ae-5e4f-9022-4290ce7b5eaa'), 'PUBLISHED', 'claude_assessment_v5'),
  ('7c65fc22-2bfd-57f0-807c-1ace0d09538d', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što se ovdje poklanja mladencima?', '["Pred Božić. Onda su zimski školski praznici.", "Ocjene se upisuju u e-Dnevnik, imat ćeš svoju lozinku.", "Obično omotnica s novcem. Takav je običaj."]'::jsonb, 2, null, '{}'::text[], 'Što se ovdje poklanja mladencima?', null, null, 'Діалог «Запрошення»: «Što se ovdje poklanja mladencima?» (Що тут дарують молодятам?) — «Obično omotnica s novcem. Takav je običaj.» (Зазвичай конверт з грошима. Такий звичай.).', (select id from public.lessons where id = '68f2ada8-2352-5450-a073-72754ae0feb8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('61ae8dd1-aaeb-5e2a-a07e-7d109d41aa65', v_aid, 7, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kakav je novi kolega?', '["Malo povučen, ali iskren i marljiv.", "Vrlo nestašan. Stalno sam se penjao po drveću.", "Volio bi igrati vaterpolo, ali članarina je skupa."]'::jsonb, 0, null, '{}'::text[], 'Kakav je novi kolega?', null, null, 'Діалог «Новий колега»: «Kakav je novi kolega?» (Який новий колега?) — «Malo povučen, ali iskren i marljiv.» (Трохи замкнутий, але щирий і працьовитий.).', (select id from public.lessons where id = '7b43692b-44ae-5e4f-9022-4290ce7b5eaa'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ca530a24-adea-5f2d-b18c-768468560813', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kolege, predlažem da radimo od kuće petkom. Slažete li se?', '["А я аж ніяк не згоден. По п’ятницях у нас найбільше клієнтів.", "Середа — добрий компроміс.", "Безумовно, я з вами згодна."]'::jsonb, 2, null, '{}'::text[], null, 'Šef: Kolege, predlažem da radimo od kuće petkom. Slažete li se?
Daša: Svakako se slažem s Vama.
Marko: Ja se nikako ne slažem. Petkom imamo najviše klijenata.
Šef: U pravu ste, Marko. Što mislite o srijedi?
Marko: Srijeda je dobar kompromis.
Šef: Dogovoreno. Od sljedećeg tjedna radimo od kuće srijedom.', 'Šef: Колеги, пропоную працювати з дому по п’ятницях. Ви згодні?
Daša: Безумовно, я з вами згодна.
Marko: А я аж ніяк не згоден. По п’ятницях у нас найбільше клієнтів.
Šef: Ви маєте рацію, Марку. Що думаєте про середу?
Marko: Середа — добрий компроміс.
Šef: Домовилися. З наступного тижня працюємо з дому по середах.', 'Діалог «Нарада»: «Kolege, predlažem da radimo od kuće petkom. Slažete li se?» — «Svakako se slažem s Vama.», тобто «Безумовно, я з вами згодна.».', (select id from public.lessons where id = 'f029711f-710e-5327-be4d-2310435e6eac'), 'PUBLISHED', 'claude_assessment_v5'),
  ('061eccba-5ad7-5acb-8925-1e95b8211d01', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Je li uvrijeđena?', '["Подзвони їй і скажи, що тобі шкода. Сварка через дрібницю того не варта.", "Так. Не озивається до мене два дні.", "Я посварилася з сестрою. Я сказала їй щось негарне."]'::jsonb, 1, null, '{}'::text[], null, 'Daša: Darja, zašto si tužna?
Darja: Posvađala sam se sa sestrom. Rekla sam joj nešto ružno.
Daša: Je li uvrijeđena?
Darja: Jest. Ne javlja mi se dva dana.
Daša: Nazovi je i reci joj da ti je žao. Svađa zbog sitnice ne vrijedi.
Darja: Imaš pravo. Nazvat ću je odmah.', 'Daša: Дар’є, чому ти сумна?
Darja: Я посварилася з сестрою. Я сказала їй щось негарне.
Daša: Вона ображена?
Darja: Так. Не озивається до мене два дні.
Daša: Подзвони їй і скажи, що тобі шкода. Сварка через дрібницю того не варта.
Darja: Ти маєш рацію. Зараз їй подзвоню.', 'Діалог «Сварка з сестрою»: «Je li uvrijeđena?» — «Jest. Ne javlja mi se dva dana.», тобто «Так. Не озивається до мене два дні.».', (select id from public.lessons where id = '6fbe028c-f4c3-50b2-b282-84f62f5d4c78'), 'PUBLISHED', 'claude_assessment_v5'),
  ('931cbc0d-41ec-5866-a647-15b2e2b64476', v_aid, 10, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я ціную щирих людей». Що ви скажете?', null, '["Živjeli! Za mladence!", "Cijenim iskrene ljude.", "Perilica se pokvarila nakon mjesec dana."]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Я ціную щирих людей.» — «Cijenim iskrene ljude.».', (select id from public.lessons where id = '7b43692b-44ae-5e4f-9022-4290ce7b5eaa'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ae62a73e-0b02-593b-9e4c-176887d5357b', v_aid, 11, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Певною мірою я погоджуюся». Що ви скажете?', null, '["Parkirali ste se na moje mjesto.", "Donekle se slažem.", "Iskrena sućut tebi i obitelji."]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Певною мірою я погоджуюся.» — «Donekle se slažem.».', (select id from public.lessons where id = 'f029711f-710e-5327-be4d-2310435e6eac'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6067195f-51d8-567e-8736-b9fa0ef59dca', v_aid, 12, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «сваритися»', null, '[]'::jsonb, null, 'svađati se', '{}'::text[], null, null, null, '«сваритися» — svađati se.', (select id from public.lessons where id = '6fbe028c-f4c3-50b2-b282-84f62f5d4c78'), 'PUBLISHED', 'claude_assessment_v5'),
  ('c3982497-6653-5f66-92df-091c4b23df24', v_aid, 13, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «На зборах ми домовилися про ремонт даху.»', null, '["popravak", "sastanku", "dogovorili", "Na", "krova.", "smo"]'::jsonb, null, 'Na sastanku smo dogovorili popravak krova.', array['Dogovorili smo popravak krova na sastanku.']::text[], null, null, null, '«На зборах ми домовилися про ремонт даху.» — «Na sastanku smo dogovorili popravak krova.».', (select id from public.lessons where id = '5252662a-abfc-517a-9bde-8683121a53c5'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b436cd7c-849f-5883-93a4-348f01f2b3bd', v_aid, 14, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «У нас зі стелі тече вода.»', null, '[]'::jsonb, null, 'Kod nas curi voda sa stropa.', '{}'::text[], null, null, null, '«У нас зі стелі тече вода.» — «Kod nas curi voda sa stropa.».', (select id from public.lessons where id = '5252662a-abfc-517a-9bde-8683121a53c5'), 'PUBLISHED', 'claude_assessment_v5');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, 'PUBLISHED', 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірки рівня A2 наново за схемою 2026-11-07 після плану «Дублі й сенс уроків» (PR 3–4) — завдання й хибні варіанти лише з уроків і текстів, які є в курсі зараз (задача власника 2026-11-19). Потрібна перевірка носієм.');
