-- Перевірка модуля A2.5 · 14 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a2-m05' and cefr = 'A2';
  if v_aid is null then raise exception 'Немає тесту a2-m05 — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = '91181bee-5ed3-5ab7-8fc8-b54cf0ec87bf') then return; end if;  -- уже оновлено
  if (select module_id from public.assessments where id = v_aid) is distinct from 'aa10630b-c7e4-5d3a-b3dc-739e9eea9e06'::uuid then
    raise exception 'Тест a2-m05 прив’язаний не до модуля A2.5 — звірте базу';
  end if;
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Після модуля: 14 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~7 хв.', estimated_minutes = 7 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('91181bee-5ed3-5ab7-8fc8-b54cf0ec87bf', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["А як надіслати йому пропозицію?", "Супер. Хто надішле коротке резюме?", "Мені треба поставити шефа в копію?"]'::jsonb, 2, null, '{}'::text[], 'Trebam li staviti šefa u kopiju?', null, null, 'Прозвучало: «Trebam li staviti šefa u kopiju?» — «Мені треба поставити шефа в копію?».', (select id from public.lessons where id = '531f3eac-8358-513b-ab35-d57fe69eb64b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a22d3278-8aac-5157-8064-4f58777b5870', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Ні, я тут. Записав, дякую за дзвінок.", "Ми не встигаємо на два дні. Команда дуже перевантажена.", "Супер. А в мене ще п’ять днів з минулого року."]'::jsonb, 1, null, '{}'::text[], 'Kasnimo s rokom dva dana. Tim je jako opterećen.', null, null, 'Прозвучало: «Kasnimo s rokom dva dana. Tim je jako opterećen.» — «Ми не встигаємо на два дні. Команда дуже перевантажена.».', (select id from public.lessons where id = '97f1ba90-fe04-5907-803f-2ec0854b0a09'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ddea0701-554b-5939-aebc-784afc17dc3c', v_aid, 3, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Перепрошую! Я надішлю вам його повторно негайно.", "Звісно. Надішлю його в тому самому листі.", "Алло? Перепрошую, погано чути."]'::jsonb, 2, null, '{}'::text[], 'Halo? Oprostite, slabo se čuje.', null, null, 'Прозвучало: «Halo? Oprostite, slabo se čuje.» — «Алло? Перепрошую, погано чути.».', (select id from public.lessons where id = 'd7b6bad3-d46a-5f73-b796-dca7b1538853'), 'PUBLISHED', 'claude_assessment_v5'),
  ('9b473f2b-e089-50fc-b05f-e066306d2680', v_aid, 4, 'A2', 'reading', 'understand', 'multiple_choice', 'Що вона надсилає в додатку?', 'Pomak roka', '["Фотографії", "Рахунок", "Новий план"]'::jsonb, 2, null, '{}'::text[], null, 'Predmet: Novi krajnji rok
Poštovana gospođo Horvat,
vezano uz novu internetsku stranicu Vaše tvrtke, ispričavam se zbog kašnjenja. Nažalost, kasnimo s rokom jer klijent još nije poslao sve fotografije. Molim Vas da pomaknemo krajnji rok s petka na sljedeću srijedu. Do tada ću sve završiti i poslati Vam kratak sažetak. U privitku je novi plan. Ako imate dodatna pitanja, stojim na raspolaganju. Unaprijed zahvaljujem.
S poštovanjem,
Darja Melnyk
voditeljica projekta', 'Тема: Новий кінцевий термін
Шановна пані Горват!
Щодо нового вебсайту вашої фірми – перепрошую за затримку. На жаль, ми не встигаємо до терміну, бо клієнт ще не надіслав усіх фотографій. Прошу вас перенести кінцевий термін із п''ятниці на наступну середу. До того часу я все закінчу й надішлю вам короткий підсумок. У додатку – новий план. Якщо маєте додаткові запитання, я до ваших послуг. Заздалегідь дякую.
З повагою,
Дар''я Мельник
керівниця проєкту', 'Текст «Прохання перенести термін». Правильна відповідь: «Новий план».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('50a6f894-0ce3-556e-bbb2-eba6abc1ead9', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Ivane, kako da počnem e-mail novom klijentu?', '["Napiši „Poštovani gospodine Horvat“, ne „Bok“.", "Do osamsto eura za četvero, ako je moguće.", "Posvađala sam se sa sestrom. Rekla sam joj nešto ružno."]'::jsonb, 0, null, '{}'::text[], 'Ivane, kako da počnem e-mail novom klijentu?', null, null, 'Діалог «Лист клієнтові»: «Ivane, kako da počnem e-mail novom klijentu?» (Іване, як мені почати e-mail новому клієнтові?) — «Napiši „Poštovani gospodine Horvat“, ne „Bok“.» (Напиши «Шановний пане Хорват», а не «Привіт».).', (select id from public.lessons where id = '531f3eac-8358-513b-ab35-d57fe69eb64b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d1bb784e-ef3f-572d-a963-8e248ea7e852', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Ivane, znaš li kad je ove godine kolektivni godišnji odmor?', '["Obje. A roditelji su oboje u Osijeku.", "Prva dva tjedna u kolovozu. Tvrtka je tada zatvorena.", "Obično omotnica s novcem. Takav je običaj."]'::jsonb, 1, null, '{}'::text[], 'Ivane, znaš li kad je ove godine kolektivni godišnji odmor?', null, null, 'Діалог «Відпустка в серпні»: «Ivane, znaš li kad je ove godine kolektivni godišnji odmor?» (Іване, знаєш, коли цього року колективна відпустка?) — «Prva dva tjedna u kolovozu. Tvrtka je tada zatvorena.» (Перші два тижні серпня. Фірма тоді зачинена.).', (select id from public.lessons where id = '0e0d07a2-2a6c-5090-ab84-3089f20a48b8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('05b50f93-db06-5d66-a474-a4b414242e36', v_aid, 7, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Trebam li knjigovodstveni servis?', '["Sjećam se, bila je stroga, ali pravedna.", "Preporučujem. Mi vodimo prihode, troškove i porez.", "Na vratima učionice. Samo ispuniš upisnicu."]'::jsonb, 1, null, '{}'::text[], 'Trebam li knjigovodstveni servis?', null, null, 'Діалог «Розмова з бухгалтеркою»: «Trebam li knjigovodstveni servis?» (Мені потрібна бухгалтерська фірма?) — «Preporučujem. Mi vodimo prihode, troškove i porez.» (Раджу. Ми ведемо доходи, витрати й податок.).', (select id from public.lessons where id = 'd9c5c952-3ae5-521d-9ccb-c22ccaeb8aab'), 'PUBLISHED', 'claude_assessment_v5'),
  ('5965cea6-108a-5cee-a1ca-2b722414046f', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Je li paušalni obrt bolji za početak?', '["Так, він простіший. Але тобі потрібен бізнес-рахунок і фіскалізація.", "Якби я мала трохи більше грошей, я б ще й орендувала приміщення.", "Спитай у службі зайнятості про грант на самозайнятість."]'::jsonb, 0, null, '{}'::text[], null, 'Darja: Ivana, htjela bih otvoriti obrt za šivanje. Kako se to radi?
Ivana: Prvo odabereš djelatnost i upišeš obrt u obrtni registar.
Darja: Je li paušalni obrt bolji za početak?
Ivana: Jest, jednostavniji je. Ali trebaš poslovni račun i fiskalizaciju.
Darja: Kad bih imala malo više novca, unajmila bih i prostor.
Ivana: Pitaj Zavod za potporu za samozapošljavanje.', 'Darja: Івано, я хотіла б відкрити обрт для шиття. Як це робиться?
Ivana: Спочатку обираєш вид діяльності й вписуєш обрт до реєстру.
Darja: Обрт на фіксованому податку кращий для початку?
Ivana: Так, він простіший. Але тобі потрібен бізнес-рахунок і фіскалізація.
Darja: Якби я мала трохи більше грошей, я б ще й орендувала приміщення.
Ivana: Спитай у службі зайнятості про грант на самозайнятість.', 'Діалог «Хочу свою справу»: «Je li paušalni obrt bolji za početak?» — «Jest, jednostavniji je. Ali trebaš poslovni račun i fiskalizaciju.», тобто «Так, він простіший. Але тобі потрібен бізнес-рахунок і фіскалізація.».', (select id from public.lessons where id = 'd9c5c952-3ae5-521d-9ccb-c22ccaeb8aab'), 'PUBLISHED', 'claude_assessment_v5'),
  ('29f9c318-5145-5d8b-ac0b-cf122d6e919f', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'O ponudi koju sam mu poslala. Možete li mu prenijeti poruku?', '["Звісно. Я скажу йому, щоб він вам передзвонив.", "Щиро дякую. Мій номер — у підписі листа.", "Компанія «Адрія Транс», слухаю вас."]'::jsonb, 0, null, '{}'::text[], null, 'Tajnica: Tvrtka Adria Trans, izvolite.
Darja: Dobar dan, ovdje je Darja Kovalenko. Mogu li razgovarati s gospodinom Horvatom?
Tajnica: Nažalost, trenutno nije dostupan, na sastanku je. O čemu se radi?
Darja: O ponudi koju sam mu poslala. Možete li mu prenijeti poruku?
Tajnica: Naravno. Reći ću mu da Vam uzvrati poziv.
Darja: Hvala lijepa. Moj broj je u potpisu e-maila.', 'Tajnica: Компанія «Адрія Транс», слухаю вас.
Darja: Добрий день, це Дар’я Коваленко. Чи можу я поговорити з паном Хорватом?
Tajnica: На жаль, зараз недоступний, він на нараді. Про що йдеться?
Darja: Про пропозицію, яку я йому надіслала. Можете передати йому повідомлення?
Tajnica: Звісно. Я скажу йому, щоб він вам передзвонив.
Darja: Щиро дякую. Мій номер — у підписі листа.', 'Діалог «Дзвінок у компанію»: «O ponudi koju sam mu poslala. Možete li mu prenijeti poruku?» — «Naravno. Reći ću mu da Vam uzvrati poziv.», тобто «Звісно. Я скажу йому, щоб він вам передзвонив.».', (select id from public.lessons where id = 'd7b6bad3-d46a-5f73-b796-dca7b1538853'), 'PUBLISHED', 'claude_assessment_v5'),
  ('3e4efaa9-bfe2-5cb1-858b-df73ca6052c9', v_aid, 10, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я хотіла б поговорити про підвищення». Що ви скажете?', null, '["Ispričavam se zbog kašnjenja.", "Dobio sam otkaz.", "Htjela bih razgovarati o povišici."]'::jsonb, 2, null, '{}'::text[], null, null, null, '«Я хотіла б поговорити про підвищення.» — «Htjela bih razgovarati o povišici.».', (select id from public.lessons where id = 'b9bcea21-08a3-56cf-be72-edf6b6c7b03f'), 'PUBLISHED', 'claude_assessment_v5'),
  ('aa353b1c-2975-5395-bd00-0730acf8ba16', v_aid, 11, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Заздалегідь дякую за відповідь». Що ви скажете?', null, '["Unaprijed zahvaljujem na odgovoru.", "Kolika je moja neto plaća?", "Trebam poslovni račun u banci."]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Заздалегідь дякую за відповідь.» — «Unaprijed zahvaljujem na odgovoru.».', (select id from public.lessons where id = '531f3eac-8358-513b-ab35-d57fe69eb64b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6347a4b1-3c00-5f53-bf4f-317e9671c8fb', v_aid, 12, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «пріоритет»', null, '[]'::jsonb, null, 'prioritet', '{}'::text[], null, null, null, '«пріоритет» — prioritet.', (select id from public.lessons where id = '97f1ba90-fe04-5907-803f-2ec0854b0a09'), 'PUBLISHED', 'claude_assessment_v5'),
  ('c9f340f7-9b4e-5a69-b41f-e257e7888834', v_aid, 13, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «У вкладенні надсилаю вам пропозицію.»', null, '["Vam", "U", "privitku", "šaljem", "ponudu."]'::jsonb, null, 'U privitku Vam šaljem ponudu.', array['Šaljem Vam ponudu u privitku.']::text[], null, null, null, '«У вкладенні надсилаю вам пропозицію.» — «U privitku Vam šaljem ponudu.».', (select id from public.lessons where id = '531f3eac-8358-513b-ab35-d57fe69eb64b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ed294be5-76fd-5d75-8918-2122dbe7b41e', v_aid, 14, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я хотіла б відкрити обрт.»', null, '[]'::jsonb, null, 'Htjela bih otvoriti obrt.', '{}'::text[], null, null, null, '«Я хотіла б відкрити обрт.» — «Htjela bih otvoriti obrt.».', (select id from public.lessons where id = 'd9c5c952-3ae5-521d-9ccb-c22ccaeb8aab'), 'PUBLISHED', 'claude_assessment_v5');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, 'PUBLISHED', 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірки рівня A2 наново за схемою 2026-11-07 після плану «Дублі й сенс уроків» (PR 3–4) — завдання й хибні варіанти лише з уроків і текстів, які є в курсі зараз (задача власника 2026-11-19). Потрібна перевірка носієм.');
