-- Перевірка модуля A2.6 · 12 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a2-m06' and cefr = 'A2';
  if v_aid is null then raise exception 'Немає тесту a2-m06 — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = '9111fa77-9b6a-5c85-ad93-605889875a36') then return; end if;  -- уже оновлено
  if (select module_id from public.assessments where id = v_aid) is distinct from 'f811eff6-8d8a-5fac-8ae7-6b78020976f1'::uuid then
    raise exception 'Тест a2-m06 прив’язаний не до модуля A2.6 — звірте базу';
  end if;
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.', estimated_minutes = 6 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('9111fa77-9b6a-5c85-ad93-605889875a36', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Коротший, будь ласка. І я хотіла б світле мелірування.", "Добре, я заплачу через інтернет-банк.", "Тридцять євро, а новий замок зі встановленням — близько ста."]'::jsonb, 0, null, '{}'::text[], 'Kraće, molim. I htjela bih svijetle pramenove.', null, null, 'Прозвучало: «Kraće, molim. I htjela bih svijetle pramenove.» — «Коротший, будь ласка. І я хотіла б світле мелірування.».', (select id from public.lessons where id = '8ab1c1e5-b217-5175-ab89-325106da3504'), 'PUBLISHED', 'claude_assessment_v5'),
  ('392aeaf2-7109-56e5-b351-26fa3d981f36', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Нотаріальний збір установлений, залежить від кількості сторінок.", "Найкраще замінити замок. Можу приїхати завтра вранці.", "«Заява про видачу довідки». Потім: «Цим листом прошу видати…»"]'::jsonb, 2, null, '{}'::text[], '„Zahtjev za izdavanje potvrde.“ Onda: „Ovim putem molim izdavanje…“', null, null, 'Прозвучало: «„Zahtjev za izdavanje potvrde.“ Onda: „Ovim putem molim izdavanje…“» — ««Заява про видачу довідки». Потім: «Цим листом прошу видати…»».', (select id from public.lessons where id = '0b5f1880-b274-51c1-9d55-32a9873040a2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('cbdeeed6-a013-5625-924f-eb20e222e2b8', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'Скільки коштує послуга?', 'U frizerskom salonu', '["35 євро", "50 євро", "20 євро"]'::jsonb, 0, null, '{}'::text[], null, 'Frizerka: Dobar dan! Jeste li naručeni?
Darja: Jesam, u deset sati. Darja Kovalenko.
Frizerka: Da, tu ste. Što želite danas?
Darja: Htjela bih se ošišati. Samo malo skratite, oko tri centimetra. I šiške, molim.
Frizerka: Može. Želite li i bojanje kose ili pramenove?
Darja: Ne, hvala, danas samo šišanje i feniranje. Koliko će to koštati?
Frizerka: Šišanje i feniranje su trideset pet eura.
Darja: U redu. Mogu li platiti karticom?
Frizerka: Naravno. Sjednite ovdje, molim.', 'Перукарка: Добрий день! Ви записані?
Дар''я: Так, на десяту. Дар''я Коваленко.
Перукарка: Так, ось ви. Чого бажаєте сьогодні?
Дар''я: Я хотіла б підстригтися. Тільки трохи вкоротіть, приблизно на три сантиметри. І чубчик, будь ласка.
Перукарка: Можна. Бажаєте ще фарбування волосся чи пасма?
Дар''я: Ні, дякую, сьогодні тільки стрижка й укладання феном. Скільки це коштуватиме?
Перукарка: Стрижка й укладання – тридцять п''ять євро.
Дар''я: Гаразд. Можна заплатити карткою?
Перукарка: Звісно. Сідайте сюди, будь ласка.', 'Текст «У перукарні». Правильна відповідь: «35 євро».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('9d751cd8-d118-5592-ab0e-1dc22162b291', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Mogu li pročitati uvjete osiguranja?', '["Deset posto. Preuzeo sam i nove zadatke.", "Ovjerena preslika diplome s apostilleom i prijepis ocjena, s prijevodom.", "Naravno, izvolite. Policu ćete dobiti e-mailom."]'::jsonb, 2, null, '{}'::text[], 'Mogu li pročitati uvjete osiguranja?', null, null, 'Діалог «Страхування квартири»: «Mogu li pročitati uvjete osiguranja?» (Можу прочитати умови страхування?) — «Naravno, izvolite. Policu ćete dobiti e-mailom.» (Звісно, прошу. Поліс ви отримаєте e-mailом.).', (select id from public.lessons where id = 'f3cfca9e-efc9-5b58-8fe9-772fa631e0c2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('8f0200ae-8c52-583f-9e01-d2f5daea11a3', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Bojanje traje dva sata. Može li sljedeći tjedan?', '["Može. Naručit ću se za utorak.", "Jesmo. Ali nakon što smo našli stan, osjetila sam olakšanje.", "Vrlo nestašan. Stalno sam se penjao po drveću."]'::jsonb, 0, null, '{}'::text[], 'Bojanje traje dva sata. Može li sljedeći tjedan?', null, null, 'Діалог «У перукарні»: «Bojanje traje dva sata. Može li sljedeći tjedan?» (Фарбування триває дві години. Можна наступного тижня?) — «Može. Naručit ću se za utorak.» (Можна. Я запишуся на вівторок.).', (select id from public.lessons where id = '8ab1c1e5-b217-5175-ab89-325106da3504'), 'PUBLISHED', 'claude_assessment_v5'),
  ('18e6e191-8c94-59a5-beb0-7d5377001ca8', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Ivana, kako da napišem zahtjev za potvrdu o prebivalištu?', '["U Supetru. Vozači moraju sići do auta prije pristajanja.", "Gore napiši svoje podatke, a ispod naslovljeno na Gradski ured.", "Jesu, prije deset godina. Grad se jako promijenio."]'::jsonb, 1, null, '{}'::text[], 'Ivana, kako da napišem zahtjev za potvrdu o prebivalištu?', null, null, 'Діалог «Як написати заяву?»: «Ivana, kako da napišem zahtjev za potvrdu o prebivalištu?» (Івано, як мені написати заяву на довідку про місце проживання?) — «Gore napiši svoje podatke, a ispod naslovljeno na Gradski ured.» (Угорі напиши свої дані, а нижче — кому адресовано: міському відділу.).', (select id from public.lessons where id = '0b5f1880-b274-51c1-9d55-32a9873040a2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e09ff593-1ca4-5b65-8c6c-1fe5607588cf', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Koji je rok završetka radova?', '["Я одразу вам повідомлю. За кожен тиждень затримки даю знижку.", "Добрий день, ми отримали ваш кошторис на плитку у ванній.", "Десять робочих днів, якщо матеріал прибуде вчасно."]'::jsonb, 2, null, '{}'::text[], null, 'Ivan: Dobar dan, dobili smo Vaš predračun za pločice u kupaonici.
Keramičar: Odlično. Imate li pitanja?
Ivan: Koji je rok završetka radova?
Keramičar: Deset radnih dana, ako materijal stigne na vrijeme.
Ivan: A ako dođe do kašnjenja radova?
Keramičar: Javit ću Vam odmah. Za svaki tjedan kašnjenja dajem popust.', 'Ivan: Добрий день, ми отримали ваш кошторис на плитку у ванній.
Keramičar: Чудово. Маєте запитання?
Ivan: Який термін завершення робіт?
Keramičar: Десять робочих днів, якщо матеріал прибуде вчасно.
Ivan: А якщо буде затримка робіт?
Keramičar: Я одразу вам повідомлю. За кожен тиждень затримки даю знижку.', 'Діалог «Кошторис на плитку»: «Koji je rok završetka radova?» — «Deset radnih dana, ako materijal stigne na vrijeme.», тобто «Десять робочих днів, якщо матеріал прибуде вчасно.».', (select id from public.lessons where id = 'bf43b6bd-d547-596b-8981-55a4043cf238'), 'PUBLISHED', 'claude_assessment_v5'),
  ('2ee8a22c-dc6f-5882-a9ee-86759ead2b63', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kako se prijavljujem?', '["Через НІАС, вам потрібні облікові дані, наприклад, з банку.", "Можете. Обидві довідки можна отримати й електронно, через е-Порезну.", "Ваш OIB, будь ласка."]'::jsonb, 0, null, '{}'::text[], null, 'Darja: Dobar dan, trebam potvrdu o dohotku za najam stana.
Službenik: Vaš OIB, molim.
Darja: Izvolite. Mogu li dobiti i potvrdu o nepostojanju duga?
Službenik: Možete. Obje potvrde se mogu dobiti i elektronički, preko e-Porezne.
Darja: Kako se prijavljujem?
Službenik: Preko NIAS-a, trebate vjerodajnicu, na primjer iz banke.', 'Darja: Добрий день, мені потрібна довідка про доходи для оренди квартири.
Službenik: Ваш OIB, будь ласка.
Darja: Прошу. Чи можу я отримати ще й довідку про відсутність боргу?
Službenik: Можете. Обидві довідки можна отримати й електронно, через е-Порезну.
Darja: Як мені увійти?
Službenik: Через НІАС, вам потрібні облікові дані, наприклад, з банку.', 'Діалог «У податковій»: «Kako se prijavljujem?» — «Preko NIAS-a, trebate vjerodajnicu, na primjer iz banke.», тобто «Через НІАС, вам потрібні облікові дані, наприклад, з банку.».', (select id from public.lessons where id = '5f9af92b-06e1-5179-81a3-19625a5b8273'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ef9803fd-03cd-5b17-a2ec-9e73a1124ed1', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Мені потрібна довіреність на сестру». Що ви скажете?', null, '["Želim prijaviti štetu.", "Trebam punomoć za sestru.", "Što pokriva polica?"]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Мені потрібна довіреність на сестру.» — «Trebam punomoć za sestru.».', (select id from public.lessons where id = '856c691f-4467-561f-a344-377ca275dbba'), 'PUBLISHED', 'claude_assessment_v5'),
  ('389e7ed1-4967-57c0-a8c1-30ed9de79c7d', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «покривати (про страховку)»', null, '[]'::jsonb, null, 'pokrivati', '{}'::text[], null, null, null, '«покривати (про страховку)» — pokrivati.', (select id from public.lessons where id = 'f3cfca9e-efc9-5b58-8fe9-772fa631e0c2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('fd932a4a-5387-545f-acce-efe6c6143e8e', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Цим листом прошу видати довідку.»', null, '["molim", "izdavanje", "Ovim", "potvrde.", "putem"]'::jsonb, null, 'Ovim putem molim izdavanje potvrde.', array['Molim ovim putem izdavanje potvrde.']::text[], null, null, null, '«Цим листом прошу видати довідку.» — «Ovim putem molim izdavanje potvrde.».', (select id from public.lessons where id = '0b5f1880-b274-51c1-9d55-32a9873040a2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('8c88c3b0-7c33-58e6-be6b-079d76e1b29b', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Чи можете засвідчити мій підпис?»', null, '[]'::jsonb, null, 'Možete li ovjeriti moj potpis?', '{}'::text[], null, null, null, '«Чи можете засвідчити мій підпис?» — «Možete li ovjeriti moj potpis?».', (select id from public.lessons where id = '856c691f-4467-561f-a344-377ca275dbba'), 'PUBLISHED', 'claude_assessment_v5');
