-- Перевірка модуля A2.7 · 12 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a2-m07' and cefr = 'A2';
  if v_aid is null then raise exception 'Немає тесту a2-m07 — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = 'c20a9573-808c-5296-b2bb-14eef172c971') then return; end if;  -- уже оновлено
  if (select module_id from public.assessments where id = v_aid) is distinct from 'd66361ac-89bc-5021-99ad-c3f61c71145c'::uuid then
    raise exception 'Тест a2-m07 прив’язаний не до модуля A2.7 — звірте базу';
  end if;
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'assessment_rebuild_20261119: перевірку зібрано наново після плану «Дублі й сенс уроків» — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.', estimated_minutes = 6 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('c20a9573-808c-5296-b2bb-14eef172c971', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Коли вам було найгірше?", "Хто їй допомагає з інсуліном?", "Мої результати вже прийшли?"]'::jsonb, 0, null, '{}'::text[], 'Kada Vam je bilo najgore?', null, null, 'Прозвучало: «Kada Vam je bilo najgore?» — «Коли вам було найгірше?».', (select id from public.lessons where id = '8f08356b-8efa-5ebc-906e-f409fbaadaf3'), 'PUBLISHED', 'claude_assessment_v5'),
  ('27d4a932-37dc-5251-928d-f8e3622afc12', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Так. Забір крові — уранці, приходьте натщесерце.", "Філіпе, не стрибай зі скель без аквашузів!", "Це схоже на професійне вигорання. Тобі треба відновити сили."]'::jsonb, 0, null, '{}'::text[], 'Da. Vađenje krvi je ujutro, dođite natašte.', null, null, 'Прозвучало: «Da. Vađenje krvi je ujutro, dođite natašte.» — «Так. Забір крові — уранці, приходьте натщесерце.».', (select id from public.lessons where id = '468ce636-fdba-5b52-9695-dc9daa6a032b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('eb4a6084-892d-5773-a166-0fb585777f24', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'До кого можна звернутися по допомогу?', 'Kad je posla previše', '["До психотерапевта або в консультаційний центр", "До перукаря", "До сусіда"]'::jsonb, 0, null, '{}'::text[], null, 'Sve više ljudi živi pod stresom. Takvi ljudi loše spavaju, bude se noću i ujutro su premoreni. Teško im je usredotočiti se na posao, a postaju i napeti i razdražljivi. Ako to traje mjesecima, može doći do izgaranja na poslu. Kako to promijeniti? Liječnici savjetuju da navečer isključite mobitel i ne čitate poslovne e-mailove. Važna je ravnoteža posla i života: šetnja, sport i boravak u prirodi pomažu nam da napunimo baterije. Ako vam je još uvijek teško, nemojte se sramiti zatražiti pomoć. Razgovor s psihoterapeutom ili u savjetovalištu može puno pomoći.', 'Дедалі більше людей живуть у стресі. Такі люди погано сплять, прокидаються вночі, а вранці вони перевтомлені. Їм важко зосередитися на роботі, і вони стають напруженими й дратівливими. Якщо це триває місяцями, може статися професійне вигорання. Як це змінити? Лікарі радять увечері вимикати мобільний і не читати робочих листів. Важливий баланс роботи й життя: прогулянка, спорт і час на природі допомагають нам зарядити батарейки. Якщо вам усе ще важко, не соромтеся попросити допомоги. Розмова з психотерапевтом або в консультаційному центрі може дуже допомогти.', 'Текст «Коли роботи забагато». Правильна відповідь: «До психотерапевта або в консультаційний центр».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('cf8b4962-9bc6-5ac3-a524-0bcdef9de40e', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Darja, tvoja baka ima šećernu bolest?', '["Jesmo. Ali nakon što smo našli stan, osjetila sam olakšanje.", "Malo povučen, ali iskren i marljiv.", "Ima. Uzima inzulin prije jela i mjeri šećer u krvi."]'::jsonb, 2, null, '{}'::text[], 'Darja, tvoja baka ima šećernu bolest?', null, null, 'Діалог «Бабуся й діабет»: «Darja, tvoja baka ima šećernu bolest?» (Дар’є, у твоєї бабусі цукровий діабет?) — «Ima. Uzima inzulin prije jela i mjeri šećer u krvi.» (Так. Вона коле інсулін перед їжею й міряє цукор у крові.).', (select id from public.lessons where id = 'd295953d-21df-54ec-9b99-7aa7b872acca'), 'PUBLISHED', 'claude_assessment_v5'),
  ('e26b6178-5d56-57df-bc0f-d1f270d4da3f', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Odlično. Uzimate li tablete redovito?', '["Preporučujem. Mi vodimo prihode, troškove i porez.", "Jednom sam preskočio dozu, zaboravio sam.", "Deset radnih dana, ako materijal stigne na vrijeme."]'::jsonb, 1, null, '{}'::text[], 'Odlično. Uzimate li tablete redovito?', null, null, 'Діалог «Мій тиск»: «Odlično. Uzimate li tablete redovito?» (Чудово. Ви регулярно приймаєте таблетки?) — «Jednom sam preskočio dozu, zaboravio sam.» (Одного разу пропустив дозу, забув.).', (select id from public.lessons where id = 'd295953d-21df-54ec-9b99-7aa7b872acca'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ea89e6b6-dacc-5bbb-b400-19bb80ffd446', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Nema već dva dana. Može li se vratiti u vrtić?', '["U Supetru. Vozači moraju sići do auta prije pristajanja.", "Može od ponedjeljka. Evo ispričnice za vrtić.", "Ovisi o prihodu. Napravimo zajedno poslovni plan."]'::jsonb, 1, null, '{}'::text[], 'Nema već dva dana. Može li se vratiti u vrtić?', null, null, 'Діалог «Довідка для садочка»: «Nema već dva dana. Može li se vratiti u vrtić?» (Уже два дні немає. Він може повернутися в садочок?) — «Može od ponedjeljka. Evo ispričnice za vrtić.» (Може з понеділка. Ось довідка для садочка.).', (select id from public.lessons where id = '8f08356b-8efa-5ebc-906e-f409fbaadaf3'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a380086b-7ced-5c0c-b4ce-453601f6cb0c', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Darja, izgledaš premoreno. Što je bilo?', '["Знаю. Цих вихідних вимкну мобільний і поїду на природу.", "Я постійно в стресі на роботі. Не можу зосередитися.", "Ні. Прокидаюся вночі, а вранці мені не хочеться вставати."]'::jsonb, 1, null, '{}'::text[], null, 'Daša: Darja, izgledaš premoreno. Što je bilo?
Darja: Stalno sam pod stresom na poslu. Ne mogu se usredotočiti.
Daša: Spavaš li dobro?
Darja: Ne. Budim se noću, a ujutro mi se ne da ustati.
Daša: To zvuči kao izgaranje na poslu. Trebaš napuniti baterije.
Darja: Znam. Ovaj vikend ću isključiti mobitel i otići u prirodu.', 'Daša: Дар’є, ти виглядаєш перевтомленою. Що сталося?
Darja: Я постійно в стресі на роботі. Не можу зосередитися.
Daša: Ти добре спиш?
Darja: Ні. Прокидаюся вночі, а вранці мені не хочеться вставати.
Daša: Це схоже на професійне вигорання. Тобі треба відновити сили.
Darja: Знаю. Цих вихідних вимкну мобільний і поїду на природу.', 'Діалог «Я втомилася»: «Darja, izgledaš premoreno. Što je bilo?» — «Stalno sam pod stresom na poslu. Ne mogu se usredotočiti.», тобто «Я постійно в стресі на роботі. Не можу зосередитися.».', (select id from public.lessons where id = '4b8782ab-0559-531b-a393-38aaf599a97c'), 'PUBLISHED', 'claude_assessment_v5'),
  ('0a70662a-9428-5c73-ae08-f9e927f5d462', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Joj! Jesi li ležao u bolnici?', '["Так. Я застудився, а потім отримав запалення легень.", "Мене виписали в п’ятницю. Поступово одужую, знову на ногах.", "Тиждень. Мене поклали через високу температуру."]'::jsonb, 2, null, '{}'::text[], null, 'Daša: Ivane, dugo te nije bilo. Jesi li bio bolestan?
Ivan: Jesam. Prehladio sam se, a onda sam dobio upalu pluća.
Daša: Joj! Jesi li ležao u bolnici?
Ivan: Tjedan dana. Primili su me zbog visoke temperature.
Daša: A sad?
Ivan: Otpustili su me u petak. Postupno se oporavljam, opet sam na nogama.', 'Daša: Іване, тебе довго не було. Ти хворів?
Ivan: Так. Я застудився, а потім отримав запалення легень.
Daša: Ой! Ти лежав у лікарні?
Ivan: Тиждень. Мене поклали через високу температуру.
Daša: А тепер?
Ivan: Мене виписали в п’ятницю. Поступово одужую, знову на ногах.', 'Діалог «Запалення легень»: «Joj! Jesi li ležao u bolnici?» — «Tjedan dana. Primili su me zbog visoke temperature.», тобто «Тиждень. Мене поклали через високу температуру.».', (select id from public.lessons where id = '266c7f3d-8fb2-5fce-8127-3b52f464ecbe'), 'PUBLISHED', 'claude_assessment_v5'),
  ('3fb5fb2e-eada-5596-89dd-84c641b9044c', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Мені важко зосередитися». Що ви скажете?', null, '["Teško mi je usredotočiti se.", "Nakon tri tjedna opet sam na nogama.", "Trebam bolovanje radi njege djeteta."]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Мені важко зосередитися.» — «Teško mi je usredotočiti se.».', (select id from public.lessons where id = '4b8782ab-0559-531b-a393-38aaf599a97c'), 'PUBLISHED', 'claude_assessment_v5'),
  ('26633eee-b802-5523-b916-da6ec5b65fb8', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «дитяча лікарка, педіатриня»', null, '[]'::jsonb, null, 'pedijatrica', '{}'::text[], null, null, null, '«дитяча лікарка, педіатриня» — pedijatrica.', (select id from public.lessons where id = '8f08356b-8efa-5ebc-906e-f409fbaadaf3'), 'PUBLISHED', 'claude_assessment_v5'),
  ('26d4d902-42fd-5432-a187-95c02402ed3c', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Сьогодні йому вже краще.»', null, '["mu", "bolje.", "već", "Danas", "je"]'::jsonb, null, 'Danas mu je već bolje.', '{}'::text[], null, null, null, '«Сьогодні йому вже краще.» — «Danas mu je već bolje.».', (select id from public.lessons where id = '8f08356b-8efa-5ebc-906e-f409fbaadaf3'), 'PUBLISHED', 'claude_assessment_v5'),
  ('dae8ede0-311c-5f23-889c-1b54dda08962', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Мені потрібен сильніший засіб від болю.»', null, '[]'::jsonb, null, 'Trebam jači lijek protiv bolova.', '{}'::text[], null, null, null, '«Мені потрібен сильніший засіб від болю.» — «Trebam jači lijek protiv bolova.».', (select id from public.lessons where id = 'd295953d-21df-54ec-9b99-7aa7b872acca'), 'PUBLISHED', 'claude_assessment_v5');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, 'PUBLISHED', 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірки рівня A2 наново за схемою 2026-11-07 після плану «Дублі й сенс уроків» (PR 3–4) — завдання й хибні варіанти лише з уроків і текстів, які є в курсі зараз (задача власника 2026-11-19). Потрібна перевірка носієм.');
end $$;

